// copierOverEmbedded is copier.Copier under the name of the field that
// copierOver embeds.
type copierOverEmbedded = copier.Copier

// copierOver is a subject of Copier whose callables call spend and return
// their zero results. The planted defect of a ceiling passes a spend that
// exceeds the ceiling.
type copierOver struct {
	copierOverEmbedded
	spend func()
}

// Copy calls spend and returns its zero results.
func (o copierOver) Copy(context.Context, string, string) (r0 error) {
	o.spend()
	return r0
}

// Open calls spend and returns its zero results.
func (o copierOver) Open(context.Context, string) (r0 error) {
	o.spend()
	return r0
}

// Close calls spend and returns its zero results.
func (o copierOver) Close(context.Context, string) (r0 error) {
	o.spend()
	return r0
}

// newCopierOver returns the planted defect of a ceiling of Copier, whose
// callables call spend.
func newCopierOver(_ *CopierHandle, spend func()) copier.Copier {
	return copierOver{spend: spend}
}

